/**
 * BA4.M5: SAMPLE practice tapes for the paper account. Fictional symbols (".S"), generated by a seeded,
 * deterministic generator in the same shape vocabulary as scenarioCharts.ts (trend, range, gap, earnings jump,
 * chop, slow grind). Gaps sit at known bar indexes so lessons and challenges can point at them.
 * Prices are in cents. Not real market data.
 */
import type { PaperBar } from "./types";
import { seeded } from "../mastery";

export type TapeShape = "trend-up" | "trend-down" | "range" | "gap-up" | "gap-down" | "earnings-jump" | "choppy" | "slow-grind";

export interface Tape {
  id: string;
  symbol: string;
  name: string;
  shape: TapeShape;
  /** One-line description for the tape picker. */
  description: string;
  /** What this tape is good for practising. */
  lesson: string;
  bars: PaperBar[];
  /** Bar indexes with a deliberate opening gap (in percent of the prior close). */
  gaps: { bar: number; pct: number }[];
}

interface Spec {
  id: string;
  symbol: string;
  name: string;
  shape: TapeShape;
  description: string;
  lesson: string;
  start: number;
  bars: number;
  /** drift per bar (fraction) for each segment [untilBar, drift] */
  drift: [number, number][];
  vol: number;
  gaps?: { bar: number; pct: number }[];
  /** mean-reversion range [low, high] in dollars */
  range?: [number, number];
}

function build(spec: Spec): Tape {
  const rnd = seeded(`tape:${spec.id}`);
  const n = (a = 1) => (rnd() * 2 - 1) * a;
  const bars: PaperBar[] = [];
  let prev = spec.start;
  for (let i = 0; i < spec.bars; i++) {
    const seg = spec.drift.find(([until]) => i < until) ?? spec.drift[spec.drift.length - 1]!;
    let drift = seg[1];
    if (spec.range) {
      const [lo, hi] = spec.range;
      const mid = (lo + hi) / 2;
      drift = ((mid - prev) / mid) * 0.18;
    }
    const gap = spec.gaps?.find((g) => g.bar === i);
    const open = gap ? prev * (1 + gap.pct / 100) : prev * (1 + n(spec.vol * 0.25));
    let close = open * (1 + drift + n(spec.vol));
    if (spec.range) close = Math.min(spec.range[1] * 1.01, Math.max(spec.range[0] * 0.99, close));
    const top = Math.max(open, close);
    const bot = Math.min(open, close);
    const high = top * (1 + Math.abs(n(spec.vol * 0.6)) + 0.001);
    const low = bot * (1 - Math.abs(n(spec.vol * 0.6)) - 0.001);
    const c = (x: number) => Math.round(x * 100);
    const b: PaperBar = { open: c(open), high: c(high), low: c(low), close: c(close), label: `D${i + 1}` };
    b.high = Math.max(b.high, b.open, b.close);
    b.low = Math.min(b.low, b.open, b.close);
    if (b.high === b.low) b.high += 1;
    bars.push(b);
    prev = close;
  }
  return { id: spec.id, symbol: spec.symbol, name: spec.name, shape: spec.shape, description: spec.description, lesson: spec.lesson, bars, gaps: spec.gaps ?? [] };
}

export const TAPES: Tape[] = [
  build({ id: "trend-up", symbol: "TRWL.S", name: "Trendwell Tools", shape: "trend-up", description: "A steady uptrend with shallow pullbacks.", lesson: "Buy a pullback, trail a stop under higher lows.", start: 50, bars: 80, drift: [[80, 0.0045]], vol: 0.012 }),
  build({ id: "trend-down", symbol: "SLWR.S", name: "Slidewater Retail", shape: "trend-down", description: "Lower highs and lower lows for weeks.", lesson: "See why buying 'cheap' in a downtrend hurts, and why a stop matters.", start: 80, bars: 80, drift: [[80, -0.004]], vol: 0.013 }),
  build({ id: "range", symbol: "RNGF.S", name: "Rangeford Foods", shape: "range", description: "Bounces between about $41 and $44.", lesson: "Patient limits near support; breakouts that fail.", start: 42.5, bars: 80, drift: [[80, 0]], vol: 0.011, range: [40, 45] }),
  build({ id: "gap-up", symbol: "LFTG.S", name: "Liftgate Software", shape: "gap-up", description: "Quiet drift, then a 9% gap up on bar 40.", lesson: "A buy stop above resistance fills at the open on a gap, above the stop.", start: 30, bars: 70, drift: [[40, 0.0005], [70, 0.003]], vol: 0.01, gaps: [{ bar: 40, pct: 9 }] }),
  build({ id: "gap-down", symbol: "DRPL.S", name: "Dropline Media", shape: "gap-down", description: "Slow rise, then an 11% gap down on bar 45.", lesson: "A stop fills at the open below the stop; a stop-limit may not fill at all.", start: 60, bars: 70, drift: [[45, 0.002], [70, -0.002]], vol: 0.01, gaps: [{ bar: 45, pct: -11 }] }),
  build({ id: "earnings-jump", symbol: "PRWD.S", name: "Printwell Devices", shape: "earnings-jump", description: "Earnings on bar 35: a 14% gap up, a pullback, then new highs.", lesson: "Position size before an event; gaps jump over orders.", start: 45, bars: 70, drift: [[35, 0.001], [50, -0.003], [70, 0.001]], vol: 0.012, gaps: [{ bar: 35, pct: 14 }] }),
  build({ id: "choppy", symbol: "CHPM.S", name: "Choppington Mining", shape: "choppy", description: "Big swings, no direction.", lesson: "Tight trails get stopped out by noise; smaller size.", start: 25, bars: 80, drift: [[20, 0.004], [40, -0.004], [60, 0.004], [80, -0.003]], vol: 0.025 }),
  build({ id: "slow-grind", symbol: "GRST.S", name: "Grindstone Utilities", shape: "slow-grind", description: "A slow, low-volatility climb.", lesson: "Patience: small daily moves add up; wide trails hold.", start: 70, bars: 80, drift: [[80, 0.0015]], vol: 0.005 }),
];

export const getTape = (id: string) => TAPES.find((t) => t.id === id);

